<?php
declare(strict_types=1);

namespace Infrastructure\Legacy;

/**
 * Parts stock, as the legacy system holds it.
 *
 * SUPPLIED BY THE COURSE. You do not edit this file, and that constraint is
 * the whole exercise: this is code you have inherited, 200 places use it, and
 * changing its shape is not on the table this quarter.
 *
 * Three columns and no behaviour. Everything that can be said about stock is
 * said somewhere else, by a service, and every service says it slightly
 * differently.
 *
 *     part_number   the SKU
 *     on_hand       how many are physically on the shelf
 *     reserved      how many of those are already promised to a job card
 *
 * The invariant nobody wrote down: RESERVED MAY NOT EXCEED ON HAND, and
 * neither may go below zero. You cannot promise the same alternator to two
 * jobs, and a shelf cannot hold minus four of anything.
 *
 * One of the three services enforces half of that. The others do not.
 */
final class PartStockRow extends ActiveRecord
{
    public static function make(string $partNumber, int $onHand, int $reserved = 0): self
    {
        return self::hydrate([
            'id'          => $partNumber,
            'part_number' => $partNumber,
            'on_hand'     => $onHand,
            'reserved'    => $reserved,
        ]);
    }
}
